#pragma once
int runTravel383(){
 juce::ScopedJuceInitialiser_GUI gui;
 auto require=[](bool pass,const char* message){if(!pass){std::cerr<<"FAIL: "<<message<<"\n";throw std::runtime_error(message);}};
 try{
 auto makeSource=[](double period,bool evolving=false){auto data=std::make_shared<AudioData>();data->rate=48000;data->buffer.setSize(2,48000*12);for(int i=0;i<data->buffer.getNumSamples();++i){double phase=2*juce::MathConstants<double>::pi*i/period,amp=evolving?.15+.6*i/data->buffer.getNumSamples():.5;float value=(float)(amp*(std::sin(phase)+(evolving?.15*std::sin(2*phase):0)));data->buffer.setSample(0,i,value);data->buffer.setSample(1,i,value*.7f);}return data;};
 auto render=[&](std::shared_ptr<AudioData> source,double travel,double ratio,int length,double outputRate=48000,bool ping=false){Processor p(false);p.audio=source;p.oneShotMode=true;p.shotEnvelope={0,0,1,.01f};p.shotLoop=true;p.shotStart=p.shotLoopStart=4096+17;p.shotEnd=source->buffer.getNumSamples();p.shotLoopEnd=p.shotLoopStart+length;p.shotLoopTravel=travel;p.shotCrossfadeMs=1;p.shotPingPong=ping;p.pitchSemitones=12*std::log2(ratio);p.loopKey=0;p.prepareToPlay(outputRate,128);p.triggerShot(60,1);std::vector<float> result;int frames=(int)(outputRate*1.5);result.reserve(frames);juce::MidiBuffer midi;juce::AudioBuffer<float> block(2,128);for(int n=0;n<frames;n+=128){block.clear();p.renderShots(block,midi);for(int i=0;i<128&&n+i<frames;++i){float value=block.getSample(0,i);require(std::isfinite(value),"finite travelling audio");require(std::abs(value*.7-block.getSample(1,i))<1e-5,"stereo phase preserved");result.push_back(value);}}double expected=juce::jmin((double)source->buffer.getNumSamples()-length,p.shotLoopStart+travel*source->rate*(frames/outputRate));require(travel==0||std::abs(p.shots[0].loopBegin-expected)<length+travel*48000*.05,"travel cursor continues scanning");return result;};
 auto frequency=[](const std::vector<float>& values,double rate){double first=-1,last=0;int intervals=-1;for(int i=(int)(rate*.2);i<(int)values.size();++i)if(values[i-1]<=0&&values[i]>0){double crossing=i-1-values[i-1]/(values[i]-values[i-1]);if(first<0)first=crossing;last=crossing;++intervals;}return intervals>0?intervals*rate/(last-first):0;};
 for(auto spec:std::vector<std::pair<double,int>>{{128,128},{127.3,127}}){auto source=makeSource(spec.first);for(double ratio:{.5,1.,2.}){auto reference=render(source,0,ratio,spec.second);double baseline=frequency(reference,48000);require(std::abs(baseline-48000.*ratio/spec.second)<.05,"reference pitch");for(double travel:{.1,.5,1.,2.,4.}){auto sound=render(source,travel,ratio,spec.second);double measured=frequency(sound,48000),cents=1200*std::log2(measured/baseline),error=0,peak=0;for(int i=9600;i<(int)sound.size();++i){error=juce::jmax(error,(double)std::abs(sound[i]-reference[i]));peak=juce::jmax(peak,(double)std::abs(sound[i]));}std::cout<<"Period "<<spec.first<<", note ratio "<<ratio<<", travel "<<travel<<": "<<measured<<" Hz, "<<cents<<" cents, max difference "<<error<<"\n";require(std::abs(cents)<1,"travel must not shift pitch");double energy=0,baseEnergy=0;for(int i=9600;i<(int)sound.size();++i){energy+=sound[i]*sound[i];baseEnergy+=reference[i]*reference[i];}require(energy/baseEnergy>.97&&peak>.45,"phase-aligned heads avoid cancellation");}}}
 auto source=makeSource(128);for(double travel:{0.,1.,4.}){auto sound=render(source,travel,1,128,44100);require(std::abs(frequency(sound,44100)-375)<.05,"different host sample rate");}
 // Scanning must still change the source, rather than simply freeze the initial cycle.
 auto evolving=makeSource(128,true);auto held=render(evolving,0,1,128),scanned=render(evolving,4,1,128);auto rms=[](const std::vector<float>& data){double energy=0;for(size_t i=data.size()-4800;i<data.size();++i)energy+=data[i]*data[i];return std::sqrt(energy/4800);};require(rms(scanned)>rms(held)*2,"travel follows evolving source");
 // Ping-pong remains bounded, including very short loops and reaching the end.
 for(int length:{1,2,128}){auto tiny=std::make_shared<AudioData>();tiny->rate=48000;tiny->buffer.setSize(2,6000);for(int i=0;i<6000;++i){float value=.2f*std::sin(i*.05);tiny->buffer.setSample(0,i,value);tiny->buffer.setSample(1,i,value*.7f);}render(tiny,4,2,length,48000,true);}
 std::cout<<"Travel pitch/phase, octave transposition, fractional source periods, host sample rates, stereo, evolving source and ping-pong bounds passed.\n";return 0;
 }catch(...){return 3831;}
}
